"""Short prompts keep context (and RAM) small. Every prompt forbids invention."""

DISCLAIMER = (
    "This is a creative memorial conversation. It is not communication with a deceased person. "
    "Answers are generated by a small local language model from the memories you wrote."
)

NO_ANSWER_TOKEN = "NO_ANSWER"
NO_ANSWER_TEXT = "I can't answer that from the memories you have saved. Add a memory about it first."
NO_MEMORIES_TEXT = "There are no saved memories yet. Add one in the Memories tab to begin."

SEANCE_SYSTEM = (
    "You narrate a fictional memorial 'memory séance'. You are NOT the person remembered and never "
    "speak as them. Answer using ONLY the numbered memories given. Use warm third-person wording, "
    "at most 4 sentences, and cite memory numbers like [1]. "
    f"If the memories do not answer the question, reply with exactly {NO_ANSWER_TOKEN}. Never invent facts."
)

OFRENDA_SYSTEM = (
    "You write short, respectful remembrances in the spirit of a Día de los Muertos ofrenda. "
    "Use ONLY facts from the numbered memories. Do not invent names, places, or events. "
    'Reply with JSON only: {"remembrance": "2-4 sentences", "remembered": ["...", "...", "..."], '
    '"closing": "one line inspired by Día de los Muertos"}. '
    '"remembered" must hold exactly three short items.'
)


def _format_memories(memories):
    lines = []
    for i, m in enumerate(memories, 1):
        when = f", {m['date']}" if m.get("date") else ""
        lines.append(f"[{i}] {m['title']} ({m['subject']}{when}): {m['text'][:600]}")
    return "\n".join(lines)


def seance_messages(question, memories):
    user = f"Memories:\n{_format_memories(memories)}\n\nQuestion: {question}"
    return [{"role": "system", "content": SEANCE_SYSTEM}, {"role": "user", "content": user}]


def ofrenda_messages(subject, memories):
    user = f"Remembering: {subject}\n\nMemories:\n{_format_memories(memories)}"
    return [{"role": "system", "content": OFRENDA_SYSTEM}, {"role": "user", "content": user}]
